const fs=require('fs'),path=require('path');const {chromium}=require('playwright');const out=path.resolve('docs/validation/deployment/nationwide-geographic-expansion/ui-evidence/map-504-preview');fs.mkdirSync(out,{recursive:true});const results={variants:[],http5xx:[],pageErrors:[],screenshots:[]};const bases=[['city-reference','http://host.docker.internal:18089'],['no-city-reference','http://host.docker.internal:18090']];(async()=>{ const browser=await chromium.launch({headless:true,executablePath:'/ms-playwright/chromium-1187/chrome-linux/chrome',args:['--no-sandbox']}); const context=await browser.newContext({acceptDownloads:true,locale:'ar-SA'}); const page=await context.newPage(); page.on('pageerror',e=>results.pageErrors.push(e.message)); page.on('console',m=>{if(m.type()==='error'&&!/status of 401|Failed to load resource: the server responded with a status of 404/.test(m.text()))results.pageErrors.push(m.text())}); page.on('response',r=>{if(r.status()>=500)results.http5xx.push(`${r.status()} ${r.url()}`)}); await page.route('https://tile.openstreetmap.org/**',r=>r.fulfill({status:200,contentType:'image/png',body:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/pN8AAAAASUVORK5CYII=','base64')})); const login=async(base)=>{await page.goto(base,{waitUntil:'domcontentloaded'});await page.waitForTimeout(500);if(!await page.locator('#loginDialog').isVisible().catch(()=>false))await page.locator('#userButton').click();await page.waitForFunction(()=>!!document.querySelector('#loginDialog')?.open,null,{timeout:10000});await page.locator('#loginEmail').fill('nwx-ui-test@example.invalid');await page.locator('#loginPassword').fill('TestOnlyAdminPassword_2026!');await page.locator('#loginForm button[type=submit]').click();await page.waitForFunction(()=>!document.querySelector('#loginDialog')?.open,null,{timeout:10000});}; const gotoView=async(view)=>{if(page.viewportSize().width<=920&&!await page.locator(`[data-view="${view}"]`).first().isVisible())await page.locator('#sidebarToggle').click();await page.locator(`[data-view="${view}"]`).first().evaluate(e=>e.click());await page.waitForTimeout(500);}; for(const [name,base] of bases){   await login(base);   const catalog=await page.evaluate(async()=>{let r=await fetch('/api/geography/catalog');return {status:r.status,body:await r.json()}});   if(catalog.status!==200||!catalog.body.national_map_enabled||!catalog.body.national_dashboard_enabled)throw Error(`${name}: map/dashboard catalog gate failed`);   await gotoView('data-dashboard');   await page.waitForFunction(()=>document.querySelector('#rdOpportunityMap')&&document.querySelector('#dashRegionFilter'),null,{timeout:10000});   const api=await page.evaluate(async()=>{const [s,m]=await Promise.all([fetch('/api/data-dashboard/geography-summary?q=TEST'),fetch('/api/data-dashboard/geography?q=TEST')]);return {summary:{status:s.status,body:await s.json()},map:{status:m.status,body:await m.json()}}});   if(api.summary.status!==200||api.summary.body.unique_master_total!==60||!api.summary.body.membership_counts_are_non_additive)throw Error(`${name}: summary response contract failed`);   if(api.map.status!==200||api.map.body.map_scope!=='NATIONAL'||api.map.body.counts.total!==60||!api.map.body.points.length)throw Error(`${name}: national map response contract failed`);   await page.locator('#dashRegionFilter').selectOption('TEST_REGION_01'); await page.waitForTimeout(450);   if(new URL(page.url()).searchParams.get('region_id')!=='TEST_REGION_01')throw Error(`${name}: Region filter did not propagate into state`);   const filteredMap=await page.evaluate(async()=>{const p=new URLSearchParams(location.search);p.set('q','TEST');const r=await fetch(`/api/data-dashboard/geography?${p}`);return {status:r.status,body:await r.json()}});   if(filteredMap.status!==200||(filteredMap.body.counts.total<=0||filteredMap.body.counts.total>60))throw Error(`${name}: Region filter changed fixture universe unexpectedly`);   await page.locator('#dashGovernorateFilter').selectOption('TEST_GOV_01'); await page.waitForTimeout(300);   if(!page.url().includes('governorate_id=TEST_GOV_01'))throw Error(`${name}: Governorate did not propagate`);   const sourceFiltered=await page.evaluate(async()=>{const r=await fetch('/api/data-dashboard/geography-summary?q=TEST&source=TEST_SOURCE_A');return {status:r.status,body:await r.json()}});   if(sourceFiltered.status!==200||sourceFiltered.body.unique_master_total!==60)throw Error(`${name}: source filter contract failed`);   await page.locator('#dashRegionFilter').selectOption(''); await page.waitForTimeout(300);   await page.waitForTimeout(300);   let popup=page.locator('#rdOpportunityMap [data-map-open]').first();   for(let i=0;i<14&&await popup.count()===0;i++){const markers=page.locator('#rdOpportunityMap .leaflet-marker-icon');if(await markers.count()===0)break;await markers.last().click({force:true});await page.waitForTimeout(180);popup=page.locator('#rdOpportunityMap [data-map-open]').first();}   if(await popup.count()===0)throw Error(`${name}: marker/cluster popup unavailable`);   const ids=await popup.getAttribute('data-map-open');if(!ids)throw Error(`${name}: marker popup missing Master IDs`);   const detailResponse=page.waitForResponse(r=>r.url().includes('/api/opportunities?')&&new URL(r.url()).searchParams.get('map_ids')===ids,{timeout:15000});   await popup.click({force:true});await detailResponse;   if(!page.url().includes(`map_ids=${ids}`))throw Error(`${name}: map-to-list drilldown URL missing marker IDs`);   await page.waitForFunction(()=>document.querySelectorAll('#opportunityRows [data-detail]').length>0,null,{timeout:10000});   await page.locator('#opportunityRows [data-detail]').first().click({force:true});await page.waitForTimeout(250);   if(await page.locator('#modal.show').count()===0)throw Error(`${name}: marker-to-opportunity detail did not open`);    await page.locator('#modalClose').click({force:true});   const viewports=[[1920,1080],[1440,900],[1366,768],[768,900],[390,844]];   for(const [w,h] of viewports){await page.setViewportSize({width:w,height:h});await gotoView('data-dashboard');await page.waitForTimeout(250);const f=await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,mapWidth:document.querySelector('#rdOpportunityMap')?.getBoundingClientRect().width||0,filterVisible:!!document.querySelector('#dashRegionFilter')?.getClientRects().length}));if(f.mapWidth<100||!f.filterVisible||f.scroll>f.width+1)throw Error(`${name}: responsive layout failed ${w}x${h}: ${JSON.stringify(f)}`);const file=path.join(out,`${name}-${w}x${h}.png`);await page.screenshot({path:file,fullPage:true});results.screenshots.push(file);}   results.variants.push({name,catalog:'PASSED',summaryMasters:api.summary.body.unique_master_total,mapMasters:api.map.body.counts.total,mapPoints:api.map.body.points.length,regionFilter:'PASSED',governorateFilter:'PASSED',sourceFilter:'PASSED',markerPopup:'PASSED',mapToList:'PASSED',opportunityDetail:'PASSED',viewports:5}); } await browser.close(); if(results.http5xx.length||results.pageErrors.length)throw Error(JSON.stringify({http5xx:results.http5xx,pageErrors:results.pageErrors})); console.log(JSON.stringify(results));})().catch(e=>{console.error(e);process.exit(1)});